require('dotenv').config();const {conectarDB}=require('../DB/dbConection');const service=require('../services/MovimientoFinanciero.service');
(async()=>{const pool=await conectarDB();try{const proyectoId=8;const antes=await service.listar(pool,proyectoId);const usuario=await pool.request().query("SELECT TOP 1 usuario_id FROM Usuario WHERE UPPER(usuario)='IRE'");const usuarioId=Number(usuario.recordset[0].usuario_id);const certificado=antes.certificados_cliente[0];let sobrepago='SIN_CERTIFICADO';if(certificado){try{await service.crear(pool,proyectoId,{tipo:'INGRESO',vinculo_tipo:'CERTIFICADO_CLIENTE',certificado_cliente_id:Number(certificado.certificado_cliente_id),fecha:'2026-08-25',importe:Number(certificado.saldo)+1,descripcion:'Prueba de sobrepago con rollback automatico'},usuarioId);sobrepago='NO_BLOQUEADO';}catch(e){sobrepago=e.status===422?'BLOQUEADO':'ERROR: '+e.message;}}let origenInvalido='NO_BLOQUEADO';try{await service.crear(pool,proyectoId,{tipo:'EGRESO',vinculo_tipo:'OC',registro_compra_id:999999999,fecha:'2026-08-25',importe:1,descripcion:'Prueba de origen inexistente'},usuarioId);}catch(e){origenInvalido=e.status===404?'BLOQUEADO':'ERROR: '+e.message;}let anulacionInexistente='NO_BLOQUEADA';try{await service.anular(pool,proyectoId,999999999,'Prueba de movimiento inexistente',usuarioId);}catch(e){anulacionInexistente=e.status===409?'BLOQUEADA':'ERROR: '+e.message;}const despues=await service.listar(pool,proyectoId);if(sobrepago==='NO_BLOQUEADO'||origenInvalido==='NO_BLOQUEADO'||anulacionInexistente==='NO_BLOQUEADA'||antes.movimientos.length!==despues.movimientos.length)throw new Error('La prueba modifico datos o no aplico los bloqueos');console.log(JSON.stringify({proyecto_id:proyectoId,listado:'OK',cantidad_movimientos:despues.movimientos.length,resumen:despues.resumen,sobrepago,origen_invalido:origenInvalido,anulacion_inexistente:anulacionInexistente,certificados_cliente:despues.certificados_cliente.length,registros_compra:despues.registros_compra.length},null,2));}finally{await pool.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
